{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 5 * 10^5",
      "description": "The number of employees is at least 1 and at most 5 * 10^5."
    },
    {
      "id": "P2",
      "expression": "1 <= k <= 8000",
      "description": "The number of teams is at least 1 and at most 8000."
    },
    {
      "id": "P3",
      "expression": "1 <= t_i <= k",
      "description": "Each employee's team number is between 1 and k, inclusive."
    },
    {
      "id": "P4",
      "expression": "Every team contains at least one employee.",
      "description": "There is at least one employee in each team."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output >= n",
      "description": "The minimum cost of the rent is at least the number of employees."
    },
    {
      "id": "Q2",
      "expression": "output == s * r",
      "description": "The output is the total cost of the rent, where s is the bus capacity and r is the number of rides."
    },
    {
      "id": "Q3",
      "expression": "all(t_i in t for t in teams) for i in range(n)",
      "description": "All employees are assigned to their respective teams."
    },
    {
      "id": "Q4",
      "expression": "no team is split across rides",
      "description": "No team is split across multiple rides; all employees of a team take the same ride."
    },
    {
      "id": "Q5",
      "expression": "no more than two teams take a ride together",
      "description": "No more than two teams take a ride together; three or more teams starting a new project is unacceptable."
    },
    {
      "id": "Q6",
      "expression": "output == min(s * r for s in range(1, n + 1) for r in range(1, (n // s) + 1) if s * r >= n)",
      "description": "The output is the minimum cost among all possible bus capacities and rides that can accommodate all employees."
    }
  ],
  "invariants": []
}
